<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, post } from '../api'
import {permissionName,scopeText,capabilityMeta,capabilityName,groupedCapabilities} from '@domain-pack/uiText'
import {authorizationUi} from '@domain-pack/uiPolicy'
import OrganizationPanel from './OrganizationPanel.vue'
const emit=defineEmits<{error:[message:string]}>()
const users=ref<any[]>([]),grants=ref<any[]>([]),catalog=ref<any>({permissions:{}}),selected=ref<any>(null),scopeResources=ref<any[]>([]),groups=ref<any[]>([])
const assignedCapabilities=ref<any[]>([]),capabilityReason=ref('')
const capabilitySearch=ref(''),capabilityDepartment=ref(''),capabilityType=ref('')
const capabilityDepartments=computed(()=>Array.from(new Map(assignedCapabilities.value.map((item:any)=>{const meta=capabilityMeta(item);return [meta.department,meta.departmentName]})).entries()))
const capabilityTypes=computed(()=>Array.from(new Map(assignedCapabilities.value.map((item:any)=>{const meta=capabilityMeta(item);return [meta.type,meta.typeName]})).entries()))
function capabilityMatches(item:any){
 const meta=capabilityMeta(item),keyword=capabilitySearch.value.trim().toLowerCase()
 if(capabilityDepartment.value&&meta.department!==capabilityDepartment.value)return false
 if(capabilityType.value&&meta.type!==capabilityType.value)return false
 if(!keyword)return true
 return [item.key,capabilityName(item),item.description,item.permission,meta.departmentName,meta.typeName].some(value=>String(value||'').toLowerCase().includes(keyword))
}
const filteredAssignedCapabilities=computed(()=>assignedCapabilities.value.filter(capabilityMatches))
const assignedCapabilityGroups=computed(()=>groupedCapabilities(filteredAssignedCapabilities.value))
const activeUserCount=computed(()=>users.value.filter((u:any)=>u.active!==false).length)
const superAdminCount=computed(()=>users.value.filter((u:any)=>u.super_admin).length)
const departmentOptions=computed(()=>groups.value.filter((g:any)=>g.kind==='DEPARTMENT'&&g.active))
const roleOptions=computed(()=>groups.value.filter((g:any)=>g.kind==='ROLE'&&g.active))
const adding=ref(false),busy=ref(false),username=ref(''),name=ref(''),department=ref(''),role=ref(''),password=ref(''),permission=ref(authorizationUi.defaultPermission),scopeResource=ref(''),category=ref(authorizationUi.defaultCategory),all=ref(false),reason=ref(''),effect=ref('ALLOW')
const permissionUnrestricted=computed(()=>authorizationUi.unrestrictedPermissions.includes(permission.value))
const permissionHint=computed(()=>authorizationUi.permissionHints[permission.value]||'')
const categoryScoped=computed(()=>authorizationUi.categoryPermissionPrefixes.some((prefix:string)=>permission.value.startsWith(prefix)))
const createDropdown=ref<'department'|'role'|''>('')
const departmentLabel=computed(()=>department.value||'选择部门')
const roleLabel=computed(()=>roleOptions.value.find((g:any)=>g.id===role.value)?.name||'暂不分配角色')
function toggleCreateDropdown(kind:'department'|'role'){createDropdown.value=createDropdown.value===kind?'':kind}
function pickDepartment(value:string){department.value=value;createDropdown.value=''}
function pickRole(value:string){role.value=value;createDropdown.value=''}
function resetCreate(){username.value='';name.value='';department.value='';role.value='';password.value='';createDropdown.value=''}
function closeCreate(){adding.value=false;resetCreate()}
function userRoles(user:any){return groups.value.filter((g:any)=>g.kind==='ROLE'&&g.members?.some((m:any)=>m.user_id===user.id)).map((g:any)=>g.name)}
async function load(){const [userData,catalogData,groupData]=await Promise.all([api('/users'),api('/catalog'),api('/organization/groups')]);users.value=userData;catalog.value=catalogData;groups.value=groupData;scopeResources.value=authorizationUi.resourceEndpoint?await api(authorizationUi.resourceEndpoint):[]}
async function choose(user:any){try{selected.value=user;[grants.value,assignedCapabilities.value]=await Promise.all([api(`/users/${user.id}/grants`),api(`/users/${user.id}/capabilities`)])}catch(e:any){emit('error',e.message)}}
async function toggleCapability(item:any){busy.value=true;try{const id=selected.value.id;await post(`/users/${id}/capabilities`,{kind:item.kind,key:item.key,enabled:!item.enabled,reason:capabilityReason.value,expected_security_version:selected.value.security_version});await load();await choose(users.value.find(u=>u.id===id))}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
onMounted(async()=>{try{await load()}catch(e:any){emit('error',e.message)}})
async function create(){busy.value=true;try{const created=await post('/users',{username:username.value,display_name:name.value,department:department.value,password:password.value});const pickedRole=groups.value.find((g:any)=>g.id===role.value);if(pickedRole){await api(`/organization/groups/${pickedRole.id}`,{method:'PUT',body:JSON.stringify({kind:pickedRole.kind,name:pickedRole.name,members:[...(pickedRole.members||[]),{user_id:created.id,is_head:false}],active:pickedRole.active,reason:'创建用户时分配角色',expected_version:pickedRole.version})})}closeCreate();await load();const fresh=users.value.find((u:any)=>u.id===created.id);if(fresh)await choose(fresh)}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
async function grant(){busy.value=true;try{const scope:any=(all.value||permissionUnrestricted.value)?{all:true}:{[authorizationUi.resourceScopeKey]:[scopeResource.value]};if(!all.value&&categoryScoped.value&&authorizationUi.categoryScopeKey)scope[authorizationUi.categoryScopeKey]=[category.value];await post(`/users/${selected.value.id}/grants`,{permission:permission.value,effect:effect.value,scope,fields:catalog.value.permissions[permission.value],reason:reason.value,expected_security_version:selected.value.security_version});const id=selected.value.id;await load();await choose(users.value.find(u=>u.id===id))}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
async function revoke(g:any){busy.value=true;try{await api(`/users/${selected.value.id}/grants/${g.id}?expected_security_version=${selected.value.security_version}`,{method:'DELETE'});const id=selected.value.id;await load();await choose(users.value.find(u=>u.id===id))}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
</script>
<template><div class="admin-permission-page"><div class="admin-page-head"><div><h2>人员与权限</h2><p class="muted">按人员维护账号、部门、角色和授权范围；角色只作为审批候选规则，不自动扩大权限。</p></div><div class="admin-head-actions"><span class="admin-stat"><strong>{{activeUserCount}}</strong> 用户</span><span class="admin-stat"><strong>{{superAdminCount}}</strong> 管理员</span><button class="primary" @click="adding=true">创建用户</button></div></div>
<section class="surface admin-user-card admin-user-list-card"><div class="admin-card-title"><div><h3>人员列表</h3><p class="muted">创建完成后统一显示在这里；点击人员可维护授权范围。</p></div></div><div class="admin-user-table" role="list"><button v-for="u in users" :key="u.id" role="listitem" :class="{active:selected?.id===u.id}" @click="choose(u)"><span class="avatar"><img v-if="u.avatar_url" :src="u.avatar_url" alt=""/><template v-else>{{u.display_name[0]}}</template></span><span class="admin-user-main"><strong>{{u.display_name}}</strong><small>{{u.username}}</small></span><span class="admin-user-cell">{{u.department||'未设置部门'}}</span><span class="admin-user-cell">{{userRoles(u).join('、')||'未分配角色'}}</span><span v-if="u.super_admin" class="admin-user-badge">超级管理员</span><span v-else class="admin-user-status">{{u.active===false?'停用':'正常'}}</span></button></div></section>
<details class="surface admin-user-card admin-organization-details"><summary><span><strong>组织与业务角色</strong><small>维护部门、通用角色和业务对象范围内的流程选人职责</small></span></summary><OrganizationPanel @changed="load" @error="emit('error',$event)"/></details>
<Teleport to="body"><div v-if="adding" class="modal-shade"><form class="modal form-stack admin-create-modal" role="dialog" aria-modal="true" aria-label="创建用户" @submit.prevent="create"><div class="admin-modal-head"><div><h2>创建用户</h2><p class="muted">填写基础人员信息，创建后自动进入人员列表。</p></div><button type="button" class="icon-button" aria-label="关闭" @click="closeCreate">×</button></div><div class="admin-create-grid"><label>登录账号<input v-model="username" required pattern="[a-zA-Z0-9_.-]{3,80}" placeholder="例如 zhangsan"/></label><label>姓名<input v-model="name" required placeholder="请输入姓名"/></label><label>部门<div class="admin-create-select" :class="{open:createDropdown==='department'}"><button type="button" class="admin-create-select-button" :disabled="!departmentOptions.length" @click="toggleCreateDropdown('department')"><span :class="{placeholder:!department}">{{departmentOptions.length?departmentLabel:'请先配置部门'}}</span><i aria-hidden="true"></i></button><div v-if="createDropdown==='department'" class="admin-create-select-menu"><button v-for="g in departmentOptions" :key="g.id" type="button" :class="{active:department===g.name}" @click="pickDepartment(g.name)">{{g.name}}</button></div></div></label><label>角色<div class="admin-create-select" :class="{open:createDropdown==='role'}"><button type="button" class="admin-create-select-button" @click="toggleCreateDropdown('role')"><span :class="{placeholder:!role}">{{roleLabel}}</span><i aria-hidden="true"></i></button><div v-if="createDropdown==='role'" class="admin-create-select-menu"><button type="button" :class="{active:!role}" @click="pickRole('')">暂不分配角色</button><button v-for="g in roleOptions" :key="g.id" type="button" :class="{active:role===g.id}" @click="pickRole(g.id)">{{g.name}}</button></div></div></label><label class="admin-create-wide">初始密码<input v-model="password" type="password" minlength="12" autocomplete="new-password" required placeholder="至少 12 位"/></label></div><p v-if="!departmentOptions.length" class="admin-create-hint muted">当前没有可用部门，先在流程或后台配置部门后再创建人员。</p><div class="actions"><button type="button" :disabled="busy" @click="closeCreate">取消</button><button class="primary" :disabled="busy||!departmentOptions.length||!department">{{busy?'正在创建…':'确定创建'}}</button></div></form></div></Teleport>
<section v-if="selected" class="surface form-stack"><h3>{{selected.display_name}}的授权</h3><p v-if="selected.super_admin" class="muted">超级管理员具有全量已实现能力，但仍受业务规则、当前席位与人工确认约束。</p>
<div v-for="g in grants.filter(x=>x.active)" :key="g.id" class="grant-row"><div><strong>{{permissionName(g.permission)}} · {{g.effect==='ALLOW'?'允许':'拒绝'}}</strong><small>{{scopeText(g.scope,scopeResources)}}</small></div><button :disabled="busy" @click="revoke(g)">撤销</button></div>
<form v-if="!selected.super_admin" @submit.prevent="grant" class="form-stack"><h3>增加一项完整授权</h3><label>业务动作<select v-model="permission"><option v-for="(_,key) in catalog.permissions" :key="key" :value="key">{{permissionName(String(key))}}</option></select></label><label>效果<select v-model="effect"><option value="ALLOW">允许</option><option value="DENY">明确拒绝</option></select></label><p v-if="permissionHint" class="muted">{{permissionHint}}</p><label v-if="!permissionUnrestricted" class="check-label"><input v-model="all" type="checkbox"/>{{authorizationUi.allScopeLabel}}</label><template v-if="!all&&!permissionUnrestricted&&authorizationUi.resourceEndpoint"><label>{{authorizationUi.resourceLabel}}<select v-model="scopeResource" required><option value="" disabled>{{authorizationUi.resourcePlaceholder}}</option><option v-for="resource in scopeResources" :key="resource.id" :value="resource.id">{{resource[authorizationUi.resourceCodeField]}}</option></select></label><label v-if="categoryScoped">{{authorizationUi.categoryLabel}}<select v-model="category"><option v-for="(label,key) in authorizationUi.categoryOptions" :key="key" :value="key">{{label}}</option></select></label></template><label>授权原因<input v-model="reason" required/></label><p class="muted">{{authorizationUi.scopeHelp}}</p><button class="primary" :disabled="busy">确认保存授权</button></form><section v-if="!selected.super_admin" class="form-stack"><h3>工具与技能</h3><p class="muted">能力分配与业务权限取交集。启用工具不会扩大数据范围；停用后，进行中的任务会停止继续使用该能力。</p><label>能力变更原因<input v-model="capabilityReason" placeholder="填写启用或停用原因"/></label><div class="capability-filter"><label>查找能力<input v-model="capabilitySearch" placeholder="输入工具、权限或说明关键词"/></label><label>部门<select v-model="capabilityDepartment"><option value="">全部部门</option><option v-for="[key,name] in capabilityDepartments" :key="key" :value="key">{{name}}</option></select></label><label>类型<select v-model="capabilityType"><option value="">全部类型</option><option v-for="[key,name] in capabilityTypes" :key="key" :value="key">{{name}}</option></select></label></div><div class="capability-groups compact capability-grid"><section v-for="department in assignedCapabilityGroups" :key="department.key" class="capability-department"><h3>{{department.name}}</h3><div v-for="type in department.types" :key="type.key" class="capability-type-block"><div class="capability-type-heading"><strong>{{type.name}}</strong><small class="muted">{{type.items.length}} 项</small></div><div v-for="item in type.items" :key="item.kind+item.key" class="grant-row capability-assignment"><div><strong>{{capabilityName(item)}} · {{item.kind==='TOOL'?'工具':'技能'}}</strong><div class="capability-tags"><span>{{capabilityMeta(item).departmentName}}</span><span>{{capabilityMeta(item).typeName}}</span></div><small>{{item.description}}</small><small>{{item.enabled?(item.effective?'已启用 · 当前可用':'已启用 · 缺少业务权限或依赖工具'):'未启用'}}</small></div><button :disabled="busy||!capabilityReason.trim()" @click="toggleCapability(item)">{{item.enabled?'停用':'启用'}}</button></div></div></section></div><p v-if="!filteredAssignedCapabilities.length" class="muted">没有匹配的工具或技能。</p></section></section></div>
</template>
